head.script:
scwin.onpageload = function() {
	var jsonData = [
		{"col1": "즐겨찾기", "col2": "1", "col3": "1"},
		{"col1": "테스트1(즐겨찾기)", "col2": "2", "col3": "2"},
		{"col1": "테스트2(즐겨찾기)", "col2": "3", "col3": "2"}
	];
	dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
	var tmpStr = "<list>";
	tmpStr += "<map>";
	tmpStr += "<col1>테스트3(즐겨찾기)</col1>";
	tmpStr += "<col2>4</col2>";
	tmpStr += "<col3>2</col3>";
	tmpStr += "</map>";
	tmpStr += "</list>";
	var tmpDoc = WebSquare.xml.parse(tmpStr);
	var tmpDocArr = WebSquare.xml.findNodes(tmpDoc, "list/map");
	var parentNode = treeview1.findNodeByValue("1");
	treeview1.appendXmlNodes(parentNode, tmpDocArr);
};
scwin.checkVal1 = function() {
	return (document.getElementById('treeview1_label_4') || document.getElementById('mf_treeview1_label_4')).innerText == '테스트3(즐겨찾기)';
};
